class Node:
    def __init__(self, val):
        self.val, self.left, self.right = val, None, None

def insert(root, v):
    if root is None:
        return Node(v)
    if v < root.val:
        root.left = insert(root.left, v)
    else:
        root.right = insert(root.right, v)
    return root

def pre(r):
    return [] if not r else [r.val] + pre(r.left) + pre(r.right)
def ino(r):
    return [] if not r else ino(r.left) + [r.val] + ino(r.right)
def post(r):
    return [] if not r else post(r.left) + post(r.right) + [r.val]

tree = None
for k in [50, 30, 70, 20, 40, 60, 80]:
    tree = insert(tree, k)
print(f'Pre={pre(tree)}, In={ino(tree)}, Post={post(tree)}')
